// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _checkDepositAlignsWithContractBalance(address depositor, uint256 sendVal) internal {
        sendVal = bound(sendVal, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendVal);
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeRecorded;
        try c.balances(depositor) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        depositor = address(this);
        try c.Deposit{value: sendVal}() {} catch { return; }
        uint256 afterContractBal = address(c).balance;
        uint256 afterRecorded;
        try c.balances(depositor) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        assertTrue((afterRecorded - beforeRecorded) == (afterContractBal - beforeContractBal));
    }

    function testFuzz_checkDepositAlignsWithContractBalance(address depositor, uint256 sendVal) public {
        _checkDepositAlignsWithContractBalance(depositor, sendVal);
    }

    receive() external payable {}
}
